//! Go structs: static descriptions generated by [`#[derive(GoJson)]`](crate::GoJson), the
//! binding plans both libraries derive from them, and the encode/decode drivers.

use std::collections::HashMap;

mod plan;

pub use plan::{JsoniterDecoder, PlanField, Plans, StringMode};

use crate::{
    encode::{Encoder, Flavor, GoEncode, jsoniter_plain_string},
    error::JsonError,
    gotype::{GoKind, GoType},
    jsoniter::{Iter, JsoniterDecode, ValueType, decode_string_mode_number},
    stdjson::{Class, Quoted, StdDecode, StdDecoder, Token, literal_store, unquote},
    unicode::{fold_name, strings_to_lower},
};

/// A Go struct type: its name and fields in declaration order.
#[derive(Clone, Copy, Debug)]
pub struct StructDesc {
    /// `reflect.Type.String()`, e.g. `openrtb2.Bid`.
    pub go_type: &'static str,
    /// False for an anonymous struct type (`reflect.Type.Name() == ""`).
    pub named: bool,
    /// The fields Go's JSON libraries see.
    pub fields: &'static [FieldDesc],
}

/// One Go struct field.
#[derive(Clone, Copy, Debug)]
pub struct FieldDesc {
    /// The Go field name (`ID`), used in jsoniter error wrapping and as the default key.
    pub go_name: &'static str,
    /// The `json:"..."` tag value (empty when there is no tag).
    pub tag: &'static str,
    /// The field type's kind.
    pub kind: GoKind,
    /// The kind behind an unnamed pointer (`encoding/json` `,string` eligibility).
    pub deref_kind: GoKind,
    /// The field type's Go name.
    pub type_name: fn(&mut String),
    /// Set for an embedded (anonymous) struct field.
    pub embedded: Option<Embedded>,
}

/// An embedded struct field.
#[derive(Clone, Copy, Debug)]
pub struct Embedded {
    /// Embedded through a pointer (`*T`, modelled as `Option<T>` or `Option<Box<T>>`).
    pub pointer: bool,
    /// The embedded struct's description.
    pub desc: fn() -> &'static StructDesc,
}

/// How a field reached through [`GoStruct::go_std_field`] is decoded.
#[derive(Clone, Copy, Debug)]
pub enum StdOp<'a> {
    /// `d.value(subv)`.
    Decode,
    /// `d.literalStore(item, subv, fromQuoted)` (a `,string` member).
    Literal(&'a [u8], bool),
}

/// A derived Go struct. Implemented by [`#[derive(GoJson)]`](crate::GoJson); the methods
/// address fields by index path, `path[0]` being an index into this struct's fields and the
/// rest continuing into an embedded struct.
pub trait GoStruct: GoType + Sized {
    /// The struct's description.
    fn go_struct_desc() -> &'static StructDesc;
    /// The struct's plans (built once).
    fn go_struct_plans() -> &'static Plans;
    /// Decodes the field at `path` with jsoniter, wrapping errors with each Go field name.
    fn go_jsoniter_field(&mut self, path: &[usize], mode: StringMode, it: &mut Iter<'_>);
    /// Decodes the field at `path` with `encoding/json`, allocating embedded pointers.
    ///
    /// # Errors
    ///
    /// Returns an error that aborts decoding.
    fn go_std_field(
        &mut self,
        path: &[usize],
        op: StdOp<'_>,
        d: &mut StdDecoder<'_>,
    ) -> Result<(), JsonError>;
    /// Encodes the field at `path`, wrapping jsoniter errors with each Go field name.
    fn go_encode_field(&self, path: &[usize], mode: StringMode, enc: &mut Encoder);
    /// The `omitempty` test for the field at `path` (true through a nil embedded pointer).
    fn go_field_is_empty(&self, path: &[usize]) -> bool;
    /// False when a nil embedded pointer is on the way to the field at `path`.
    fn go_field_reachable(&self, path: &[usize]) -> bool;
}

/// Decodes a leaf field with jsoniter under its `,string` mode.
pub fn jsoniter_leaf<T: JsoniterDecode + ?Sized>(v: &mut T, mode: StringMode, it: &mut Iter<'_>) {
    match mode {
        StringMode::None => v.jsoniter_decode(it),
        StringMode::Number => decode_string_mode_number(v, it),
        StringMode::String => v.jsoniter_decode_string_mode(it),
    }
}

/// Decodes a leaf field with `encoding/json`.
///
/// # Errors
///
/// Returns an error that aborts decoding.
pub fn std_leaf<T: StdDecode + ?Sized>(
    v: &mut T,
    op: StdOp<'_>,
    d: &mut StdDecoder<'_>,
) -> Result<(), JsonError> {
    match op {
        StdOp::Decode => v.std_decode(d),
        StdOp::Literal(item, from_quoted) => v.std_literal(item, from_quoted, d),
    }
}

/// Encodes a leaf field under its `,string` mode.
pub fn encode_leaf<T: GoEncode + ?Sized>(v: &T, mode: StringMode, enc: &mut Encoder) {
    match (mode, enc.flavor()) {
        (StringMode::None, _) => v.go_encode(enc),
        (StringMode::Number | StringMode::String, Flavor::Std { .. }) => v.go_encode_quoted(enc),
        (StringMode::Number, Flavor::Jsoniter) => {
            // Go: json-iterator/go reflect_extension.go stringModeNumberEncoder
            enc.write_byte(b'"');
            v.go_encode(enc);
            enc.write_byte(b'"');
        }
        (StringMode::String, Flavor::Jsoniter) => {
            // Go: stringModeStringEncoder (the inner stream's error is dropped)
            let mut inner = Encoder::new(Flavor::Jsoniter);
            v.go_encode(&mut inner);
            let mut quoted = Vec::with_capacity(inner.len() + 8);
            jsoniter_plain_string(&mut quoted, inner.as_bytes());
            enc.write_raw(&quoted);
        }
    }
}

/// jsoniter struct decoding (`skipObjectDecoder`, the hashed decoders, or
/// `generalStructDecoder`).
pub fn jsoniter_decode_struct<S: GoStruct>(v: &mut S, it: &mut Iter<'_>) {
    // Go: json-iterator/go reflect_struct_decoder.go
    let plans = S::go_struct_plans();
    match &plans.jsoniter_decoder {
        JsoniterDecoder::Skip => {
            let next = it.what_is_next();
            if next != ValueType::Object && next != ValueType::Nil {
                it.report_error("skipObjectDecoder", b"expect object or null");
                return;
            }
            it.skip();
        }
        JsoniterDecoder::Hashed(fields) => decode_hashed(v, fields, plans, it),
        JsoniterDecoder::General(fields) => decode_general(v, fields, plans, it),
    }
}

fn wrap_struct_error<S: GoStruct>(it: &mut Iter<'_>) {
    let desc = S::go_struct_desc();
    if desc.named {
        it.wrap_error(desc.go_type, ".");
    }
}

fn decode_binding<S: GoStruct>(v: &mut S, plans: &Plans, index: usize, it: &mut Iter<'_>) {
    if let Some(field) = plans.jsoniter_bindings.get(index) {
        v.go_jsoniter_field(&field.path, field.mode, it);
    }
}

fn decode_hashed<S: GoStruct>(
    v: &mut S,
    fields: &[(i64, usize)],
    plans: &Plans,
    it: &mut Iter<'_>,
) {
    // Go: oneFieldStructDecoder … tenFieldsStructDecoder
    if !it.read_object_start() {
        return;
    }
    if !it.increment_depth() {
        return;
    }
    loop {
        let hash = it.read_field_hash();
        match fields.iter().find(|(h, _)| *h == hash) {
            Some(&(_, index)) => decode_binding(v, plans, index, it),
            None => it.skip(),
        }
        if it.is_object_end() {
            break;
        }
    }
    wrap_struct_error::<S>(it);
    it.decrement_depth();
}

fn decode_general<S: GoStruct>(
    v: &mut S,
    fields: &HashMap<Vec<u8>, usize>,
    plans: &Plans,
    it: &mut Iter<'_>,
) {
    // Go: generalStructDecoder.Decode / decodeOneField
    if !it.read_object_start() {
        return;
    }
    if !it.increment_depth() {
        return;
    }
    let mut c = b',';
    while c == b',' {
        let field = it.read_string();
        let found = fields
            .get(&field)
            .or_else(|| fields.get(&strings_to_lower(&field)))
            .copied();
        let colon = it.next_token();
        if colon != b':' {
            it.report_error_byte(
                "ReadObject",
                "expect : after object field, but found ",
                colon,
            );
        }
        match found {
            Some(index) => decode_binding(v, plans, index, it),
            None => it.skip(),
        }
        c = it.next_token();
    }
    wrap_struct_error::<S>(it);
    if c != b'}' {
        it.report_error_byte("struct Decode", "expect }, but found ", c);
    }
    it.decrement_depth();
}

/// `encoding/json` struct `object(v)`: members matched by exact then case-folded name, with
/// Go's error context; unknown members are skipped.
///
/// # Errors
///
/// Returns an error that aborts decoding.
pub fn std_decode_struct<S: GoStruct>(v: &mut S, d: &mut StdDecoder<'_>) -> Result<(), JsonError> {
    // Go: encoding/json/decode.go object (struct case)
    let plans = S::go_struct_plans();
    let desc = S::go_struct_desc();
    let struct_name = if desc.named { desc.go_type } else { "" };
    let mark = d.context_mark();
    let Some(mut key) = d.object_begin() else {
        return Ok(());
    };
    loop {
        let name = unquote(key).unwrap_or_default();
        let index = plans
            .std_exact
            .get(&name)
            .or_else(|| plans.std_folded.get(&fold_name(&name)))
            .copied();
        match index.and_then(|i| plans.std_fields.get(i)) {
            Some(field) => {
                let _restore = d.enter_field(struct_name, &field.embedded_names, &field.name);
                if field.mode == StringMode::None {
                    v.go_std_field(&field.path, StdOp::Decode, d)?;
                } else {
                    std_quoted_member(v, field, d)?;
                }
            }
            None => d.skip(),
        }
        d.restore_context(mark);
        match d.object_next() {
            Some(next) => key = next,
            None => return Ok(()),
        }
    }
}

fn std_quoted_member<S: GoStruct>(
    v: &mut S,
    field: &PlanField,
    d: &mut StdDecoder<'_>,
) -> Result<(), JsonError> {
    match d.value_quoted() {
        Quoted::Null => v.go_std_field(&field.path, StdOp::Literal(b"null", false), d),
        Quoted::Str(qv) => v.go_std_field(&field.path, StdOp::Literal(&qv, true), d),
        Quoted::Unquoted => {
            let mut text = String::from(
                "json: invalid use of ,string struct tag, trying to unmarshal unquoted value into ",
            );
            (field.leaf.type_name)(&mut text);
            d.save_error(JsonError::Message(text.into_bytes()));
            Ok(())
        }
    }
}

/// `encoding/json` `value(v)` for a struct type `N`: objects decode the fields, other values
/// are type mismatches (`null` is ignored).
///
/// # Errors
///
/// Returns an error that aborts decoding.
pub fn std_decode_struct_as<N: GoType + ?Sized, S: GoStruct>(
    v: &mut S,
    d: &mut StdDecoder<'_>,
) -> Result<(), JsonError> {
    match d.peek() {
        Token::Object => std_decode_struct(v, d),
        Token::Array => {
            d.type_error::<N>("array");
            d.skip();
            Ok(())
        }
        Token::Literal => {
            let item = d.read_literal();
            std_struct_literal::<N>(item, false, d)
        }
    }
}

/// `literalStore` into a struct type `N` (every literal but `null` is a mismatch).
///
/// # Errors
///
/// Returns the `,string` misuse errors Go returns.
pub fn std_struct_literal<N: GoType + ?Sized>(
    item: &[u8],
    from_quoted: bool,
    d: &mut StdDecoder<'_>,
) -> Result<(), JsonError> {
    let _store = literal_store::<N>(item, from_quoted, d, Class::Other)?;
    Ok(())
}

/// Struct encoding in the encoder's flavour.
pub fn encode_struct<S: GoStruct>(v: &S, enc: &mut Encoder) {
    let plans = S::go_struct_plans();
    match enc.flavor() {
        Flavor::Jsoniter => {
            // Go: json-iterator/go reflect_struct_encoder.go structEncoder / emptyStructEncoder
            let Some(fields) = &plans.jsoniter_encode else {
                enc.write_raw(b"{}");
                return;
            };
            enc.write_byte(b'{');
            let mut first = true;
            for field in fields {
                if (field.omitempty && v.go_field_is_empty(&field.path))
                    || !v.go_field_reachable(&field.path)
                {
                    continue;
                }
                if !first {
                    enc.write_byte(b',');
                }
                enc.write_field_name(&field.name);
                v.go_encode_field(&field.path, field.mode, enc);
                first = false;
            }
            enc.write_byte(b'}');
            enc.wrap_error(S::go_struct_desc().go_type, ".");
        }
        Flavor::Std { .. } => {
            // Go: encoding/json/encode.go structEncoder.encode
            let mut first = true;
            for field in &plans.std_fields {
                if !v.go_field_reachable(&field.path)
                    || (field.omitempty && v.go_field_is_empty(&field.path))
                {
                    continue;
                }
                enc.write_byte(if first { b'{' } else { b',' });
                first = false;
                enc.write_field_name(&field.name);
                v.go_encode_field(&field.path, field.mode, enc);
            }
            if first {
                enc.write_raw(b"{}");
            } else {
                enc.write_byte(b'}');
            }
        }
    }
}
